    prime_used = [[] for _ in range(n + 1)]

    for i in range(2, n + 1):
        for prime in primes:
            if prime > i:
                break
            if dp[i - prime] + 1 > dp[i]:
                dp[i] = dp[i - prime] + 1
                prime_used[i] = prime_used[i - prime] + [prime]

    print(dp[n])
    print(" ".join(map(str, prime_used[n])))

